import sys

def main():
    data = sys.stdin.buffer.read().split()
    n = int(data[0]); m = int(data[1])
    Ps = list(map(int, data[2:2 + n]))

    try:
        import numpy as np
        use_np = True
    except ImportError:
        use_np = False

    if use_np:
        P = np.array(Ps, dtype=np.int64)
        CAP_C = np.int64(2_000_000_000)
        CAP2 = 2_000_000_000_000_000_000 // P  # per-product cap on c^2
        MASK = (1 << 21) - 1

        def total_cost(v):
            c = ((v // P) + 1) >> 1
            np.minimum(c, CAP_C, out=c)
            t2 = c * c
            np.minimum(t2, CAP2, out=t2)
            term = P * t2  # <= 2e18, fits int64; clamped terms are > M
            return int((term >> 21).sum()) * (1 << 21) + int((term & MASK).sum())

        def count_at(v):
            return int((((v // P) + 1) >> 1).sum())
    else:
        Ps.sort(reverse=True)

        def total_cost(v):
            total = 0
            for p in Ps:
                c = (v // p + 1) >> 1
                if c:
                    total += p * c * c
                    if total > m:
                        break
            return total

        def count_at(v):
            cnt = 0
            for p in Ps:
                cnt += (v // p + 1) >> 1
            return cnt

    lo, hi = 0, 2 * 10 ** 15  # sum(2e15) > 1e18 >= M guaranteed
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if total_cost(mid) <= m:
            lo = mid
        else:
            hi = mid - 1
    v = lo
    total = total_cost(v)
    cnt = count_at(v)
    print(cnt + (m - total) // (v + 1))

main()

