import sys

def main():
    S = sys.stdin.readline().strip()
    stack = []
    for c in S:
        if c == 'A' and stack and stack[-1] == 'W':
            k = 0
            while stack and stack[-1] == 'W':
                stack.pop()
                k += 1
            stack.append('A')
            stack.extend(['C'] * k)
        else:
            stack.append(c)
    sys.stdout.write(''.join(stack) + '\n')

main()

