    while d * d * d < N:
        if N % d == 0:
            M = N // d
            disc = 12 * M - 3 * d * d
            if disc >= 0:
                s = isqrt(disc)
                if s * s == disc:
                    num = s - 3 * d
                    if num > 0 and num % 6 == 0:
                        y = num // 6
                        if y >= 1:
                            print(y + d, y)
                            return
        d += 1
    print(-1)

