def main():
    data = sys.stdin.read().split()
    N = int(data[0]); R = int(data[1]); C = int(data[2]); S = data[3]
    dr = {'N': -1, 'S': 1, 'W': 0, 'E': 0}
    dc = {'N': 0, 'S': 0, 'W': -1, 'E': 1}
    r = c = 0
    seen = {(0, 0)}
    out = []
    for ch in S:
        r += dr[ch]
        c += dc[ch]
        out.append('1' if (r - R, c - C) in seen else '0')
        seen.add((r, c))
    sys.stdout.write(''.join(out) + '\n')

main()
